import{_ as e,c as i,o as l,ak as r}from"./chunks/framework.CtX3_w5e.js";const b=JSON.parse('{"title":"Spring Cloud","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"Spring Cloud","hugoSource":"computer-science/distributed-system/spring-cloud.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/distributed-system/2026-11-17-spring-cloud.md","filePath":"computer-science/distributed-system/2026-11-17-spring-cloud.md","lastUpdated":1794887319000}'),n={name:"computer-science/distributed-system/2026-11-17-spring-cloud.md"};function o(d,a,h,t,s,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="spring-cloud" tabindex="-1">Spring Cloud <a class="header-anchor" href="#spring-cloud" aria-label="Permalink to “Spring Cloud”">​</a></h1><h2 id="服务注册与发现" tabindex="-1">服务注册与发现 <a class="header-anchor" href="#服务注册与发现" aria-label="Permalink to “服务注册与发现”">​</a></h2><h3 id="eureka" tabindex="-1">Eureka <a class="header-anchor" href="#eureka" aria-label="Permalink to “Eureka”">​</a></h3><ul><li>Netflix 开源的服务注册中心，采用 AP 架构（高可用性），通过心跳机制检测服务状态</li><li>包含 Eureka Server（注册中心）和 Eureka Client（服务提供者/消费者）</li><li>注：Eureka 2.x 已停止维护，建议新项目使用 Nacos</li></ul><h3 id="nacos" tabindex="-1">Nacos <a class="header-anchor" href="#nacos" aria-label="Permalink to “Nacos”">​</a></h3><ul><li>Spring Cloud Alibaba 的核心组件，兼具服务注册中心和配置中心功能，支持 CP/AP 模式切换</li><li>提供动态服务发现、健康检查、配置管理等功能，适用于云原生场景</li></ul><h2 id="服务调用与负载均衡" tabindex="-1">服务调用与负载均衡 <a class="header-anchor" href="#服务调用与负载均衡" aria-label="Permalink to “服务调用与负载均衡”">​</a></h2><h3 id="feign" tabindex="-1">Feign <a class="header-anchor" href="#feign" aria-label="Permalink to “Feign”">​</a></h3><ul><li>声明式的 REST 客户端，通过动态代理简化服务间 HTTP 调用，整合了 Ribbon 实现负载均衡</li></ul><h3 id="ribbon" tabindex="-1">Ribbon <a class="header-anchor" href="#ribbon" aria-label="Permalink to “Ribbon”">​</a></h3><ul><li>客户端负载均衡组件，支持轮询、随机、权重等算法，需配合 Eureka/Nacos 使用</li><li>注：Ribbon 已进入维护阶段，Spring Cloud LoadBalancer 是新一代替代方案</li></ul><h3 id="dubbo" tabindex="-1">Dubbo <a class="header-anchor" href="#dubbo" aria-label="Permalink to “Dubbo”">​</a></h3><ul><li>Spring Cloud Alibaba 支持的 RPC 框架，适用于高性能服务调用，替代 Feign+Ribbon 的组合</li></ul><h2 id="服务容错与熔断" tabindex="-1">服务容错与熔断 <a class="header-anchor" href="#服务容错与熔断" aria-label="Permalink to “服务容错与熔断”">​</a></h2><h3 id="hystrix" tabindex="-1">Hystrix <a class="header-anchor" href="#hystrix" aria-label="Permalink to “Hystrix”">​</a></h3><ul><li>Netflix 开源的熔断器，通过熔断、降级、隔离机制防止服务雪崩</li><li>注：Hystrix 已停止维护，推荐使用 Sentinel</li></ul><h3 id="sentinel" tabindex="-1">Sentinel <a class="header-anchor" href="#sentinel" aria-label="Permalink to “Sentinel”">​</a></h3><ul><li>Alibaba 开源的流量控制组件，支持熔断、限流、系统自适应保护，提供实时监控</li></ul><h2 id="服务网关" tabindex="-1">服务网关 <a class="header-anchor" href="#服务网关" aria-label="Permalink to “服务网关”">​</a></h2><h3 id="zuul" tabindex="-1">Zuul <a class="header-anchor" href="#zuul" aria-label="Permalink to “Zuul”">​</a></h3><ul><li>Netflix 的 API 网关，负责路由、过滤、负载均衡，但性能较低</li><li>注：Zuul 1.x 已停止维护，Zuul 2.x 未集成到 Spring Cloud</li></ul><h3 id="spring-cloud-gateway" tabindex="-1">Spring Cloud Gateway <a class="header-anchor" href="#spring-cloud-gateway" aria-label="Permalink to “Spring Cloud Gateway”">​</a></h3><ul><li>基于 Reactor 的高性能网关，支持动态路由、限流、集成 Sentinel</li></ul><h2 id="配置中心" tabindex="-1">配置中心 <a class="header-anchor" href="#配置中心" aria-label="Permalink to “配置中心”">​</a></h2><h3 id="spring-cloud-config" tabindex="-1">Spring Cloud Config <a class="header-anchor" href="#spring-cloud-config" aria-label="Permalink to “Spring Cloud Config”">​</a></h3><ul><li>集中化管理配置，支持 Git、本地存储等，但需配合 Bus 实现动态刷新</li></ul><h3 id="nacos-config" tabindex="-1">Nacos Config <a class="header-anchor" href="#nacos-config" aria-label="Permalink to “Nacos Config”">​</a></h3><ul><li>与 <code>Nacos</code> 注册中心无缝集成，支持配置动态更新和版本管理</li></ul><h2 id="消息总线与事件驱动" tabindex="-1">消息总线与事件驱动 <a class="header-anchor" href="#消息总线与事件驱动" aria-label="Permalink to “消息总线与事件驱动”">​</a></h2><h3 id="spring-cloud-bus" tabindex="-1">Spring Cloud Bus <a class="header-anchor" href="#spring-cloud-bus" aria-label="Permalink to “Spring Cloud Bus”">​</a></h3><ul><li>通过消息队列（如 RabbitMQ、Kafka）广播配置变更，实现配置热更新</li></ul><h3 id="spring-cloud-stream" tabindex="-1">Spring Cloud Stream <a class="header-anchor" href="#spring-cloud-stream" aria-label="Permalink to “Spring Cloud Stream”">​</a></h3><ul><li>统一消息中间件抽象层，支持 Kafka、RocketMQ 等</li></ul><h2 id="分布式链路追踪" tabindex="-1">分布式链路追踪 <a class="header-anchor" href="#分布式链路追踪" aria-label="Permalink to “分布式链路追踪”">​</a></h2><h3 id="sleuth-zipkin" tabindex="-1">Sleuth + Zipkin <a class="header-anchor" href="#sleuth-zipkin" aria-label="Permalink to “Sleuth + Zipkin”">​</a></h3><ul><li>追踪微服务调用链路，生成请求依赖图，便于故障排查</li></ul><h3 id="skywalking" tabindex="-1">SkyWalking <a class="header-anchor" href="#skywalking" aria-label="Permalink to “SkyWalking”">​</a></h3><ul><li>更强大的 APM 工具，支持分布式追踪、性能监控</li></ul><h2 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to “分布式事务”">​</a></h2><h3 id="seata" tabindex="-1"><code>Seata</code> <a class="header-anchor" href="#seata" aria-label="Permalink to “Seata”">​</a></h3><ul><li>Alibaba 开源的分布式事务解决方案，支持 AT、TCC、SAGA 模式</li></ul><h2 id="其他组件" tabindex="-1">其他组件 <a class="header-anchor" href="#其他组件" aria-label="Permalink to “其他组件”">​</a></h2><h3 id="spring-cloud-security" tabindex="-1">Spring Cloud Security <a class="header-anchor" href="#spring-cloud-security" aria-label="Permalink to “Spring Cloud Security”">​</a></h3><ul><li>OAuth2、JWT 等安全认证</li></ul><h3 id="spring-cloud-openfeign" tabindex="-1">Spring Cloud OpenFeign <a class="header-anchor" href="#spring-cloud-openfeign" aria-label="Permalink to “Spring Cloud OpenFeign”">​</a></h3><ul><li>Feign 的增强版，支持 Spring MVC 注解</li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2>',47)])])}const g=e(n,[["render",o]]);export{b as __pageData,g as default};
